import{_ as i,C as a,o as n,c as d,a6 as t,E as s}from"./chunks/framework.5dd0l9Wo.js";const f=JSON.parse('{"title":"Cross-Site Request Forgery (CSRF)","description":"Ambient credentials, SameSite, token validation flaws, Referer checks, and method overrides.","frontmatter":{"title":"Cross-Site Request Forgery (CSRF)","description":"Ambient credentials, SameSite, token validation flaws, Referer checks, and method overrides."},"headers":[],"relativePath":"csrf/index.md","filePath":"csrf/index.md"}'),c={name:"csrf/index.md"};function l(h,e,p,u,g,m){const o=a("LabGroup"),r=a("TopicComplete");return n(),d("div",null,[e[0]||(e[0]=t('<h1 id="cross-site-request-forgery-csrf-·-the-case-of-the-borrowed-identity" tabindex="-1">Cross-Site Request Forgery (CSRF) · The Case of the Borrowed Identity <a class="header-anchor" href="#cross-site-request-forgery-csrf-·-the-case-of-the-borrowed-identity" aria-label="Permalink to &quot;Cross-Site Request Forgery (CSRF) · The Case of the Borrowed Identity&quot;">​</a></h1><p class="wd-section-lede">Cross-Site Request Forgery (CSRF) does not steal your password or read your private messages. Instead, it borrows your logged-in browser session to perform actions behind your back. Because web browsers automatically attach your login cookies to any request destined for a site, a server that doesn&#39;t verify user intent can be tricked into obeying an attacker&#39;s orders.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Stamped Signature Stamp.</strong> Imagine keeping an official corporate signature stamp in your desk drawer. Whenever a courier walks in carrying a fund transfer document, the front-desk clerk stamps it with your official seal without asking whether you drafted it or if a stranger handed it to the messenger. The bank processes the transfer because the stamp is authentic—even though you never knew the paper existed.</p></div><h2 id="case-file-1-tracing-the-silent-cross-site-post" tabindex="-1">Case File #1: Tracing the Silent Cross-Site Post <a class="header-anchor" href="#case-file-1-tracing-the-silent-cross-site-post" aria-label="Permalink to &quot;Case File #1: Tracing the Silent Cross-Site Post&quot;">​</a></h2><p>Let&#39;s follow what happens when an attacker tries to change the email address on your shopping account.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You are logged into your favorite shop in Tab 1. In Tab 2, you click a link to read a funny blog post or forum thread. The blog page looks completely normal, but behind the scenes, an invisible form submits itself instantly.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The blog page contains a hidden HTML form pointing to <code>https://shop.example/my-account/change-email</code>. JavaScript triggers <code>form.submit()</code>. Because the target domain is <code>shop.example</code>, the user&#39;s browser automatically attaches their existing session cookie:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Legitimate Session Cookie (Attached by Browser)</span><span><span class="wd-code-input">Gold</span> = Attacker&#39;s Injected Form Data</span></div><span class="wd-code-dev">POST /my-account/change-email HTTP/1.1</span><br><span class="wd-code-dev">Host: shop.example</span><br><span class="wd-code-dev">Cookie: session=7f9d8a3bc410e52</span><br><span class="wd-code-input">email=attacker@malicious-domain.com</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The shop&#39;s server looks at the request and asks only one question: <em>&quot;Does this request have a valid session cookie?&quot;</em> Finding the cookie, it assumes the user clicked the button on the real account page. It changes the email address to the attacker&#39;s email, enabling a password reset takeover!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers protect endpoints by requiring an unguessable <strong>anti-CSRF token</strong> in the request body. When the real account page loads, the server generates a secret, cryptographically random token tied to the user&#39;s session. Because external sites cannot read the shop&#39;s DOM due to the Same-Origin Policy, the attacker cannot supply the matching token.</p></div></div><h3 id="visual-comparison-user-intent-vs-ambient-cookie-delivery" tabindex="-1">Visual Comparison: User Intent vs. Ambient Cookie Delivery <a class="header-anchor" href="#visual-comparison-user-intent-vs-ambient-cookie-delivery" aria-label="Permalink to &quot;Visual Comparison: User Intent vs. Ambient Cookie Delivery&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer assumed that receiving a POST request accompanied by a valid session cookie meant the account holder deliberately filled out the settings form and clicked &quot;Save Changes&quot;.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>The request originated from a totally different website. Because browsers attach cookies to cross-site requests by default (&quot;ambient credentials&quot;), the server processed the state change without verifying the user&#39;s actual intent.</p></div></div><hr><h2 id="the-5-stages-of-a-cross-site-request" tabindex="-1">The 5 Stages of a Cross-Site Request <a class="header-anchor" href="#the-5-stages-of-a-cross-site-request" aria-label="Permalink to &quot;The 5 Stages of a Cross-Site Request&quot;">​</a></h2><p>For a CSRF attack to succeed, the request travels through five key moments:</p><div class="wd-flow"><div class="wd-flow__node wd-flow__node--safe"><strong>1. Victim Authenticates</strong> User logs into target site; browser receives and stores the session cookie. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Visits External Site</strong> Victim opens attacker&#39;s lure page or blog in another browser tab. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Auto-Submit Form</strong> Lure page&#39;s JavaScript secretly triggers a cross-origin POST request. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>4. Ambient Cookie Sent</strong> Browser automatically attaches target&#39;s session cookies with the request. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>5. Action Executed</strong> Target server executes change, believing the victim authorized it. </div></div><details class="details custom-block"><summary>🔬 Under the Hood: The Three Pillars of a CSRF Vulnerability</summary><p>A CSRF vulnerability requires three conditions to be true at the same time:</p><ol><li><strong>A Relevant Action:</strong> The target endpoint performs a meaningful state change (e.g. changing an email, transferring money, or altering account permissions).</li><li><strong>Cookie-Based Session Handling:</strong> The application relies entirely on browser cookies to identify the user, rather than authorization headers or custom request tokens.</li><li><strong>No Unpredictable Parameters:</strong> The request structure is completely predictable—the attacker knows all necessary parameters, and no unpredictable secret is required.</li></ol></details><hr><h2 id="unprotected-endpoints-the-baseline-case" tabindex="-1">Unprotected Endpoints: The Baseline Case <a class="header-anchor" href="#unprotected-endpoints-the-baseline-case" aria-label="Permalink to &quot;Unprotected Endpoints: The Baseline Case&quot;">​</a></h2><p>When an endpoint accepts standard form POST requests and relies purely on session cookies, an attacker can craft a simple self-submitting HTML page to trigger the action.</p>',16)),s(o,{ids:"csrf-lab-no-defenses"}),e[1]||(e[1]=t('<hr><h2 id="flawed-token-validation-the-5-detective-checkpoints" tabindex="-1">Flawed Token Validation: The 5 Detective Checkpoints <a class="header-anchor" href="#flawed-token-validation-the-5-detective-checkpoints" aria-label="Permalink to &quot;Flawed Token Validation: The 5 Detective Checkpoints&quot;">​</a></h2><p>Many applications implement anti-CSRF tokens, but validate them incorrectly. An investigator checks each link in the validation chain to find where the logic breaks down:</p><table tabindex="0"><thead><tr><th>Flaw Category</th><th>What the Server Does Wrong</th><th>How the Check Fails</th></tr></thead><tbody><tr><td><strong>Method Dependence</strong></td><td>Only validates token on <code>POST</code> requests</td><td>Changing the request method to <code>GET</code> skips the check entirely</td></tr><tr><td><strong>Token Presence</strong></td><td>Only validates token if the parameter exists</td><td>Deleting the <code>csrf</code> parameter from the request bypasses validation</td></tr><tr><td><strong>Session Binding</strong></td><td>Checks if token is valid, but not <em>whose</em> token it is</td><td>Supplying the attacker&#39;s own valid token satisfies the check</td></tr><tr><td><strong>Non-Session Cookie</strong></td><td>Binds token to a separate tracking cookie</td><td>Injecting a cookie via header injection allows forging a valid pair</td></tr><tr><td><strong>Double-Submit Flaw</strong></td><td>Verifies body token matches a cookie token</td><td>If an attacker can set cookies (subdomain or CRLF), they set both values</td></tr></tbody></table>',4)),s(o,{ids:"csrf-lab-token-validation-depends-on-request-method, csrf-lab-token-validation-depends-on-token-being-present, csrf-lab-token-not-tied-to-user-session, csrf-lab-token-tied-to-non-session-cookie, csrf-lab-token-duplicated-in-cookie"}),e[2]||(e[2]=t('<details class="details custom-block"><summary>🔬 Under the Hood: The Double-Submit Cookie Pattern</summary><p>The &quot;Double-Submit Cookie&quot; pattern avoids storing tokens in a server-side database. Instead, the server sets a random cookie <code>csrf=xyz</code> and requires the client to send <code>csrf=xyz</code> in the form body. When the request arrives, the server simply compares the two strings.</p><p><strong>The weakness:</strong> If the attacker has any way to plant a cookie onto the victim&#39;s domain (such as via an open redirect, header injection, or an insecure sibling subdomain like <code>forum.target.com</code>), the attacker sets the cookie to <code>hacked</code> and submits <code>csrf=hacked</code> in the body. Because both match, the server accepts the forged request!</p></details><hr><h2 id="samesite-cookie-restrictions-and-bypasses" tabindex="-1">SameSite Cookie Restrictions and Bypasses <a class="header-anchor" href="#samesite-cookie-restrictions-and-bypasses" aria-label="Permalink to &quot;SameSite Cookie Restrictions and Bypasses&quot;">​</a></h2><p>The <code>SameSite</code> cookie attribute tells the browser when to include cookies on cross-site requests:</p><ul><li><strong><code>SameSite=Strict</code>:</strong> Never sends the cookie on any cross-site request, even when following a regular link.</li><li><strong><code>SameSite=Lax</code>:</strong> Default in modern browsers. Blocks cookies on cross-site POST requests, but permits cookies on top-level GET navigations (like clicking a link).</li></ul><p>Even with <code>SameSite</code> enabled, subtle flaws can leave endpoints exposed:</p><ol><li><strong>Method Override:</strong> Some web frameworks let incoming GET requests override their HTTP verb using <code>_method=POST</code> or query parameters. A <code>SameSite=Lax</code> cookie is carried on the top-level GET request, which the backend then executes as a POST!</li><li><strong>Client-Side Open Redirects:</strong> An open redirect on the target site can turn a cross-site top-level navigation into a same-site request, carrying Strict cookies along for the ride.</li><li><strong>Sibling Domains:</strong> <code>app.example.com</code> and <code>marketing.example.com</code> are considered same-site. A vulnerability on a sibling domain allows forging requests to the main application.</li></ol>',7)),s(o,{ids:"csrf-lab-samesite-lax-bypass-via-method-override, csrf-lab-samesite-strict-bypass-via-client-side-redirect, csrf-lab-samesite-strict-bypass-via-sibling-domain"}),e[3]||(e[3]=t('<hr><h2 id="referer-based-defenses" tabindex="-1">Referer-Based Defenses <a class="header-anchor" href="#referer-based-defenses" aria-label="Permalink to &quot;Referer-Based Defenses&quot;">​</a></h2><p>Some applications attempt to prevent CSRF by checking the HTTP <code>Referer</code> header to ensure requests originate from their own domain. This defense is notoriously brittle:</p><ul><li><strong>Missing Referer:</strong> If the server only checks the <code>Referer</code> header when it is present, setting <code>&lt;meta name=&quot;referrer&quot; content=&quot;no-referrer&quot;&gt;</code> on the attacking page strips the header completely, bypassing the check.</li><li><strong>Broken Substring Matching:</strong> A naive regular expression checking for <code>bank.example</code> can be satisfied by hosting the exploit on <code>bank.example.attacker.com</code> or <code>attacker.com?target=bank.example</code>.</li></ul>',4)),s(o,{ids:"csrf-lab-referer-validation-depends-on-header-being-present, csrf-lab-referer-validation-broken"}),e[4]||(e[4]=t('<details class="details custom-block"><summary>⚙️ Framework Quirks: Where Default CSRF Protection Drops</summary><ul><li><strong>Django:</strong> <code>CsrfViewMiddleware</code> protects all unsafe methods by default, but views decorated with <code>@csrf_exempt</code> disable protection entirely.</li><li><strong>Ruby on Rails:</strong> <code>protect_from_forgery</code> is standard, but developers sometimes use <code>skip_before_action :verify_authenticity_token</code>.</li><li><strong>Spring Security:</strong> CSRF is enabled by default for browser sessions, but frequently disabled globally when developers configure stateless API endpoints.</li><li><strong>Express.js:</strong> Does not provide CSRF protection out of the box; developers must manually install and configure modern middleware.</li></ul></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The Detective&#39;s Defense Blueprint.</strong> Bind unpredictable, cryptographically random CSRF tokens to the user&#39;s server-side session. Validate tokens strictly on all state-changing methods. Configure session cookies with <code>SameSite=Lax</code> or <code>Strict</code>, <code>Secure</code>, and <code>HttpOnly</code>. Never permit sensitive state modifications over GET requests.</p></div>',2)),s(r,{"topic-id":"cross-site-request-forgery-csrf",label:"Mark CSRF complete"})])}const k=i(c,[["render",l]]);export{f as __pageData,k as default};
